class std::strstreambuf : public basic_streambuf<char> {
    // Internal state: control flags (dynamic vs fixed, free vs frozen)
    int _str_flags; 

    // Overrides handle dynamic resizing or fixed buffer boundaries:
    int_type overflow(int_type c) override;
    int_type underflow() override;
    pos_type seekoff(off_type off, std::ios_base::seekdir dir, 
                     std::ios_base::openmode which) override;

    // Internally manages basic_streambuf pointers:
    // Put area manipulation:
    void setp(char* p_beg, char* p_end); // Setup pbase() to epptr()

    // Get area manipulation:
    void setg(char* g_beg, char* g_curr, char* g_end); 

    // Example: Overflow triggers if pptr == epptr()
    // New buffer is allocated, data copied, setp() called.
};
